function getJobPayPeriodRangeForReceiveMonth(job, offset = 0) {
      const now = new Date();
      let year = now.getFullYear();
      let receiveMonth = now.getMonth() + offset;

      let closeDayInput = String(job.closeDay || '20').trim();
      let payDayInput = String(job.payDay || '5').trim();

      let closeNum = (closeDayInput === '月末') ? 31 : (Number(closeDayInput) || 20);
      let isEndMonth = closeNum >= 31;
      let payNum = (payDayInput === '月末') ? 31 : (Number(payDayInput) || 5);

      let workMonth = receiveMonth - 1;
      if (payNum >= closeNum) {
        workMonth = receiveMonth;
      }

      let start, end;
      if (isEndMonth) {
        start = new Date(year, workMonth, 1);
        end = new Date(year, workMonth + 1, 0);
      } else {
        const clampedClose = (y, m) => new Date(y, m, Math.min(closeNum, new Date(y, m + 1, 0).getDate()));
        const prevClose = clampedClose(year, workMonth - 1);
        start = new Date(prevClose.getFullYear(), prevClose.getMonth(), prevClose.getDate() + 1);
        end = clampedClose(year, workMonth);
      }
      return { start, end };
    }

