function calcJobCalendarMonthPay(jk, viewMonth) {
      const job = configData[jk];
      // 表示月の翌月に入金される予定の締め期間を、バイト先別に求める。
      const todayMonth = new Date();
      const receiveMonthOffset = (viewMonth.getFullYear() - todayMonth.getFullYear()) * 12
        + (viewMonth.getMonth() - todayMonth.getMonth()) + 1;
      const {start, end} = getJobPayPeriodRangeForReceiveMonth(job, receiveMonthOffset);
      let mins = 0, pay = 0, days = 0, commutingDays = 0;
      for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
        const r = calcJobDay(formatDateKey(d), jk, new Date(d));
        mins += r.mins;
        pay += r.pay;
        if (r.worked) days++;
        if (r.commuted) commutingDays++;
      }
      const other = (days > 0 ? (job.transMonth || 0) + (job.allowanceMonth || 0) : 0)
        + commutingDays * ((job.transDay || 0) + (job.allowanceDay || 0));
      if (days > 0) pay += (job.transMonth || 0) + (job.allowanceMonth || 0);
      const roundPay = n => Math.floor(Math.round(n * 1000) / 1000);
      return { pay: roundPay(pay), wagePay: roundPay(pay - other), otherPay: roundPay(other), mins, days, start, end, wageMissing: test5HasMissingWage(jk, start, end) };
    }

functions.calculateJobShiftMinutesAndPay:
function calculateJobShiftMinutesAndPay(jobShift, job, dateObj) {
      if (!jobShift) return { totalMins: 0, totalPay: 0 };
      if (jobShift.isPaidLeave) return { totalMins: 0, totalPay: paidLeaveAmount(job, jobShift) };
      let rateSum = 0;
      const totalMins = forEachWorkMinute(jobShift, min => { rateSum += getRateForMinuteDetailed(min, job, dateObj, false).rate; });
      return { totalMins, totalPay: rateSum / 60 };
    }

